Database Layer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(database_layer, "Database Layer") {
    Component(PostgreSQL_Primary_Node, "PostgreSQL Primary Node", "PostgreSQL (AWS RDS/Aurora EU-Central)", "Persists transactional writes such as checkouts and fines with ACID compliance.")
    Component(PostgreSQL_Read_Only_Replica, "PostgreSQL Read-Only Replica", "PostgreSQL (AWS RDS/Aurora EU-Central)", "Executes reads and search hydrations to protect core transactional performance.")
    Component(PgBouncer_Connection_Pooler_Sidecar, "PgBouncer Connection Pooler Sidecar", "PgBouncer", "Manages and pools database connections to prevent connection exhaustion under peak patron load.")
    Component(Partitioned_Storage_Engine, "Partitioned Storage Engine", "PostgreSQL Partitioned Storage", "Optimizes catalogue and circulation data storage.")
}

Rel(PgBouncer_Connection_Pooler_Sidecar, PostgreSQL_Primary_Node, "Forwards client identity for auditing", "TLS 1.3")
Rel(PgBouncer_Connection_Pooler_Sidecar, PostgreSQL_Read_Only_Replica, "Forwards client identity for auditing", "TLS 1.3")
@enduml

Elasticsearch.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(Elasticsearch, "Elasticsearch") {
    Component(Routing and Coordination Node, "Routing and Coordination Node", "Java / Netty", "Handles client requests, query distribution, security filtering, and cluster-state management.")
    Component(Data Nodes, "Data Nodes", "Lucene Engine", "Store index shards, doc-values, and execute distributed matching across EU availability zones.")
    Component(Inverted Index & Analyzer Pipeline, "Inverted Index & Analyzer Pipeline", "Elasticsearch Analyzer", "Implements custom tokenizers, stemmers, fuzzy matching, and domain-specific synonyms.")
    Component(Search Microservice, "Search Microservice", "Java / Spring Boot", "Acts as the sole intermediary between API gateways and Elasticsearch, issuing search/indexing queries over REST / JSON over TLS 1.3.")
}

Rel(Search Microservice, Routing and Coordination Node, "Issues search/indexing queries", "REST / JSON over TLS 1.3")
Rel(Routing and Coordination Node, Data Nodes, "Distributes search/index operations", "Transport Protocol over TLS 1.3 (mTLS)")

@enduml
